import{_ as t,a as o,b as a}from"./chunks/f0929a2bf23cb619ed62.B9l9wUoF.js";import{_ as n,o as i,c as s,a5 as r}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"You Aren’t Successful Because You Care Too Much (How To Stop Caring)","description":"","frontmatter":{"title":"You Aren’t Successful Because You Care Too Much (How To Stop Caring)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring.md","filePath":"en/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring.md"}'),p={name:"en/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring.md"};function l(u,e,h,c,d,y){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="you-aren-t-successful-because-you-care-too-much-how-to-stop-caring" tabindex="-1">You Aren’t Successful Because You Care Too Much (How To Stop Caring) <a class="header-anchor" href="#you-aren-t-successful-because-you-care-too-much-how-to-stop-caring" aria-label="Permalink to &quot;You Aren’t Successful Because You Care Too Much (How To Stop Caring)&quot;">​</a></h1><p>Dan Koe · 2023-07-29 · <a href="https://thedankoe.com/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/you-arent-successful-because-you-care-too-much-how-to-stop-caring">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/U1tVnANCDH0?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>You stop caring about others’ opinions when you trust yourself with your future.</p><p>That… is a lot to unpack.</p><p>Lack of confidence is the one thing that plagues the potential of the majority of the population. They care too much about what others think.</p><p>Let’s say you want to start a business and the thoughts start to flood in:</p><p>What will my parents think?</p><p>What will my friends think?</p><p>What will my spouse think?</p><p>Will it be enough to replace my income?</p><p>How long will it take?</p><p>Don’t even get me started on the thoughts that come when you actually start building the business.</p><p>The reason people fail is they can’t lift the emotional weights required to achieve the goals they set.</p><p>For every thought of a better life, there are 100 thoughts beating you back down.</p><p>And that’s just thoughts about business.</p><p>What about the other 60-80,000 thoughts we have in a day?</p><p>We have a lot on our plate.</p><p>Will I come off as weird when I try to make new friends?</p><p>Where will I end up in life if I don’t get my debt under control?</p><p>Did I feed the dog this morning? Imagine how terrible of a pet owner people would think I am if they found out.</p><p>Developing self-confidence is no easy task.</p><p>More information, more responsibilities, and more options for our future turns confidence into success and anxiety into failure.</p><p>This is the modern environment we live in.</p><p>How do we begin to cultivate the trust in ourselves that leads to self-confidence?</p><h2 id="the-4-pillars-of-self-confidence" tabindex="-1">The 4 Pillars Of Self-Confidence <a class="header-anchor" href="#the-4-pillars-of-self-confidence" aria-label="Permalink to &quot;The 4 Pillars Of Self-Confidence&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>When most people wonder how they can become more confident, they are reminded of the simplistic advice:</p><p>“Confidence = competence.”</p><p>This is true, but most people will see competence as getting better at a specific skill.</p><p>So they’ll learn and learn and learn, never act, never self-reflect, and never actually develop confidence as a skill in any situation. This is the most common outcome.</p><p>There is depth behind that simple statement that few can see.</p><p>We must seek to understand that statement, because clearly “confidence = competence” as general advice has not fixed one of the biggest problems in the world, but has made it worse.</p><p><strong>Pillar 1) Perspective</strong></p><p>When you enter a situation where you don’t feel confident, anxiety shoots through the roof.</p><p>This closes your mind to everything but your thoughts.</p><p>They multiply.</p><p>You completely retract from the situation and become a slave to your past. The experiences you’ve had before. You remain the same person.</p><p>You must snap out of this and make a conscious effort to reprogram your habitual way of reacting to situations.</p><p>To do this:</p><ul><li>When you enter a situation and anxiety sparks, pause</li><li>Zoom out to see the situation for what it is, just a normal situation</li><li>Transfer consciousness to those in the situation with you</li></ul><p>“Transferring consciousness” is adopting another person’s perspective.</p><p>Most people are just people living the same experience as us.</p><p>Billionaires are people with the same problems.</p><p>Fitness models are people with the same problems.</p><p>Any person you mentally place above you has the same problems.</p><p>The ONE thing that will make them react in a negative way to you is treating them like they aren’t human.</p><p>Don’t put them above you.</p><p>Remember, this is a habit you are forming.</p><p>It will take repetition and practice.</p><p>You cannot advance to the other pillars if you do not gain perspective on a situation.</p><p><strong>Pillar 2) Perception</strong></p><p>How you perceive situations determines how you act.</p><p>This requires you to shift into an open-minded state before and maintain it during, the situation.</p><p>If you are scrolling social media and don’t perceive a business owner’s tweet as an opportunity to reach out, you won’t reach out.</p><p>If you do see it as an opportunity, you still may botch the message or not send one at all because you misperceive that individual.</p><p>The same goes for making new friends or engaging in difficult discussions.</p><p>Perception goes two ways.</p><p>You perceive others in a certain way based on how they present themselves.</p><p>They perceive you based on how you present yourself.</p><p>If you don’t “look the part” or hold yourself in a way that would lead to a positive interpretation by the other party, it won’t go well. And you will know this subconsciously. You won’t engage in situations because you set yourself up for failure in the way you look and act.</p><p>I’m as introverted as they come, but people often tell me I look confident in the way I dress, walk, and talk.</p><p>Practice.</p><p><strong>Pillar 3) Practice</strong></p><p>How good you are at something allows you to perceive situations better.</p><p>Think of skill acquisition as a way to increase your level in the game of life.</p><p>In a video game there are “skill trees.”</p><p>As you play the game, you choose skills to help you play how you want.</p><p>As you practice those skills, you increase your experience, and new skills become available to you.</p><p>The key point here:</p><p><em>You are not able to access other skills until you practice the ones available to you.</em></p><p>You don’t have the awareness of profitable opportunities because you don’t have the skill to recognize, choose, and act on them.</p><p>As you move toward your goals, it will require that you educate and practice skills to reach those goals.</p><p>If you aim too high, you get overwhelmed and don’t know what to learn.</p><p>You must play at your level and acquire the skills necessary to reach the next level.</p><p>As your level increases, you fill your toolbelt with skills that allow you to view the plane you are on, which is more vast than the lower level you were at.</p><p>My first successful endeavor was freelance web design.</p><p>A single skill that is available for anyone to learn. Lots of competition and battling for higher prices.</p><p>I knew that if I wanted to do something more profitable, like funnels for service businesses, I would have to learn skills like marketing, copywriting, and buyer’s journey to do that well.</p><p>Then, when I pursued the level of a creator, I needed to combine what I knew and add new skills like content writing (I teach all skills you need in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>).</p><p>The higher my level grew, the more people I met, and the more my confidence throughout multiple domains increased.</p><p>The worst thing you can do is stop learning new skills and settle for the level you are at.</p><p><strong>Pillar 4) Authenticity</strong></p><p>Authenticity is doing what you want without interference from external thoughts, opinions, and beliefs that you feel the need to conform to.</p><p>When I curse, and people in the comments tell me that’s unprofessional, do I conform to their relative beliefs (that aren’t absolute truth) or do I think for myself?</p><p>I don’t care to be professional. I don’t care to be offended by words that every single person interprets in a different way.</p><p>Confidence through authenticity is a mental game.</p><p>You must play it daily.</p><p>You must pause, gain perspective, perceive the situation, and practice the skill that the situation requires.</p><p>Authenticity is how you implement the 4 Pillars of Self-Confidence.</p><h2 id="the-unconventional-path-to-self-confidence" tabindex="-1">The Unconventional Path To Self-Confidence <a class="header-anchor" href="#the-unconventional-path-to-self-confidence" aria-label="Permalink to &quot;The Unconventional Path To Self-Confidence&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>Entrepreneurship is in your nature.</p><p>To pursue new challenges, never settle, expand your perspective through skill acquisition, and get feedback on if you are actually contributing to society in the form of money.</p><p>Entrepreneurship is creation.</p><p>And being a creator is the act of channeling the divine through your human edge.</p><p>You don’t want to get stuck in a situation where challenge ceases to exist.</p><p>Like a monkey in a cubicle, your psyche will suffer, and you will wonder why your life isn’t fulfilling even if you are a top 1% earner.</p><p>Personal growth is a gateway drug into business growth.</p><p>And business growth is the unconventional path to self-confidence.</p><p>I combine the two in <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> so you can improve yourself, productize yourself, and earn from being yourself. A natural progression.</p><p><strong>1) It demands that you evolve, or die.</strong></p><p>Most people die at 25.</p><p>They get their job.</p><p>They get their spouse.</p><p>They get their house.</p><p>They get their car.</p><p>They get exactly what society wants for them. Someone who is comfortable, docile, and of little threat to their system they are trying to survive.</p><p>Life is ever-flowing, ever-evolving, and if you choose to obstruct that flow by settling for a sub-par life, you’re dead.</p><p>Death is symbolic. And all understanding is metaphorical.</p><p>If life is growth, and growth requires new, death is the death of new ideas, potentials, projects, and practices.</p><p>If you want to survive in a world that never stops changing, entrepreneurship ensures that you don’t. If you persist until success, that is.</p><p><strong>2) It demands you to become an expert in your industry.</strong></p><p>If you have subpar understanding you will get subpar results.</p><p>Understanding is different from knowledge.</p><p>Understanding is the upward motion of expanding consciousness.</p><p>Meditation is the downward motion of expanding consciousness.</p><p>Most mystics and spiritual teachers forget this balance.</p><p>It’s not creativity <em>or</em> productivity.</p><p>It’s not monk <em>or</em> warrior.</p><p>It’s not peace <em>or</em> progress.</p><p>It’s not being <em>or</em> doing.</p><p>It’s both.</p><p>It’s life.</p><p>The duality collapses into one.</p><p>If you stack theory without practice, you will fail in this business.</p><p>You need both daily education and execution. Not one or the other.</p><p><strong>3) It demands you get results for yourself and your customers.</strong></p><p>If you don’t get results, you aren’t valuable.</p><p>Simple as that.</p><p>If you aren’t getting results, that isn’t a sign to quit. It’s a sign to improve. True value requires development over time.</p><p>Entrepreneurship is how you ensure that you develop yourself into a valuable asset in reality.</p><p><strong>4) It demands that you suck at what you’re doing so you can improve.</strong></p><p>It is foolish to think that you will not suck at almost everything at the start.</p><p>This is what keeps most people from acting on their dreams.</p><p>Once you overcome the first hump, you snowball into a season of pure progress.</p><p><strong>5) It demands that you change your work, rest, and play habits.</strong></p><p>You cannot reach level 3 with the character that got you to level 2.</p><p>Growth requires change and that’s why most people settle early.</p><p><strong>6) It demands a skill set in psychology so you understand your mind.</strong></p><p>Marketing, sales, writing, and speaking are the backbone of business success.</p><p>In today’s world, wealth is generated through code and content.</p><p>Code is the back end of the internet.</p><p>Content is the front end.</p><p>Combine both and you have people and product.</p><p>Send people to product and you have profit.</p><p>You can learn to code, which is incredibly valuable, but unless that is a passion of yours you are better off learning content.</p><p>You can build using what the coders build (like website builders, social media platforms, and everything else on the internet) to distribute your content.</p><p>Content requires self-understanding.</p><p>You must capture attention, hold attention, and deliver value to that attention.</p><p>I discuss this in <a href="/letters/the-1-million-dollar-skill-stack-learn-in-this-order">The $1 Million Dollar Skill Stack</a>.</p><h2 id="a-potential-progression-for-self-improvers" tabindex="-1">A Potential Progression For Self-Improvers <a class="header-anchor" href="#a-potential-progression-for-self-improvers" aria-label="Permalink to &quot;A Potential Progression For Self-Improvers&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>The anxiety trap is dangerous when you attempt to become more confident.</p><p>You get anxious approaching new people.</p><p>You get anxious about the change required to build a business.</p><p>When you feel it, pause.</p><p>(No, seriously, this is going to take a conscious effort… <em>pause.</em>)</p><p>Zoom out.</p><p>Reframe your mind.</p><p>The cure to anxiety is curiosity.</p><p>That’s it. That’s the reframe.</p><p>When you’re anxious about starting a business, you are projecting so far into the future that clarity is impossible. Your mind cannot bring order to the chaotic situation you mentally reside in.</p><p>Bring your attention back to what you can do right now.</p><p>Get curious about what you can start learning, then learn it.</p><p>When you are in a social situation, stop imagining every little detail about the future with that person.</p><p>Focus your attention on them, right in front of you.</p><p>What is something that catches your eye?</p><p>Ask them about it.</p><p>Here’s how you can leverage curiosity to build momentum into a profitable business (with self-confidence as a byproduct).</p><p><strong>1) Start With Writing</strong></p><p>When you aren’t confident, writing is your best bet.</p><p>And, it’s the foundation of any and all content.</p><p>Tweets, ads, videos, reels, etc all start with writing the actual post or a script.</p><p>Writing allows you to flex your intelligence while everyone else competes for looks.</p><p>You don’t have to show your body, or even your face for that matter. (<a href="https://twitter.com/orangebook_" target="_blank" rel="noreferrer">Orange Book</a> is one of my favorite anonymous writers.)</p><p>To become a good writer, you will need to understand psychology to structure a message that captures, holds, and spreads attention.</p><p>To understand psychology, study marketing and sales. That’s how you learn to apply your psychological understanding in the real world.</p><p>If I were to give you a path, here’s how to start writing:</p><ul><li>Choose a topic you are interested in making your full-time gig</li><li>Block out 30 minutes to learn about marketing, sales, or your interest</li><li>Do not skip a day of learning. Watch videos, podcasts, read books and internet content.</li><li>Take notes on the ideas that stick out to you.</li><li>Start on Twitter (X) or Threads and start posting your ideas.</li><li>Study social media as a skill so you can grow (I teach all of this in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>).</li></ul><p>In the course of 3-6 months, you should gain a decent amount of followers.</p><p>Enough to give you confidence that you can make this your full-time business.</p><p>Once you have enough readers, you can create a product or service to monetize your writing.</p><p>The marketing and sales knowledge will compound at this moment.</p><p><strong>2) Branch Into Speaking</strong></p><p>Most people don’t know this, but the first platform I branched out to was not Instagram. It was a podcast.</p><p>Why?</p><ul><li>It helped me meet high-level people and get offered more opportunities.</li><li>You don’t need video editing skills. It is an easy progression from writing.</li><li>It forces you to identify your blind spots in communicating with other people.</li></ul><p>I didn’t use a podcast to monetize or become famous.</p><p>That is incredibly rare with podcasting.</p><p>I used it to get people I wanted to talk to on a call.</p><p>People LOVE getting on podcasts.</p><p>I wanted to talk with Justin Welsh, so I asked him to do a podcast, and that gave new vision for my brand.</p><p>Our chat on one-person businesses was the catalyst for me gaining 150k subscribers in less than 6 weeks on YouTube.</p><p>That’s another next step.</p><p>You can go straight to YouTube with your previous writing.</p><p>You can literally see the increase in confidence you get after creating 6 months of videos.</p><p>You become less awkward, more concise, and more impactful.</p><p>Your business compounds as your confidence does.</p><p><strong>3) Create A Product Or Service</strong></p><p>By now you are growing an audience.</p><p>You have people.</p><p>Well, hopefully. If you don’t, you need to zoom out and realize it’s a skill issue. You need a big picture understanding of social media to get eyes on good content however you can.</p><p>Money requires people and a product.</p><p>“Product” can also include services here. It is what you sell to the people you’ve attracted.</p><p>This is the only way to make money.</p><p>You can aim to be one of the select few that lives off of ad revenue (generated from the social media platform) alone, but you will be a slave to the algorithm.</p><p>Creating your own product or service is how you take control of your income.</p><p>Social media as a skill becomes a faucet that you can turn on whenever you want to make more money.</p><p>You know how to attract people and you have a product that sells.</p><p>(There’s a lot that goes into both, you will need to improve at both.)</p><p>I’ve written about this extensively, so here are some letters to learn how to create a product:</p><p>– <a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">An overview of the one person business model</a></p><p>– <a href="/letters/the-best-online-business-model-to-make-1-million-in-2023">The best way to create an offer even as a beginner</a></p><p>– <a href="/letters/you-have-100000-of-knowledge-trapped-in-your-brain">How to productize the $100,000 worth of knowledge in your head</a></p><p>The reason building a product or service helps with confidence is this:</p><ul><li>You will suck at first. This is the case for literally anything else you do. Don’t see it as scary just because business seems foreign to you.</li><li>You get direct feedback on what can be improved. People can be brutal, but most are nice.</li><li>If you want to actually make money, you need to actually provide value. If you aren’t continuing to grow your audience or money – maybe start thinking about how valuable you really are.</li></ul><p>That’s it for this one my friends.</p><p>Go practice confidence as a skill, for life.</p><p>– Dan Koe</p>',220)])])}const w=n(p,[["render",l]]);export{g as __pageData,w as default};
